import json, subprocess, warnings
warnings.filterwarnings("ignore")
from TTS.utils.synthesizer import Synthesizer
lines = [
 "चाबी कहीं रखकर भूल जाना आम बात है. पर घर का रास्ता भूल जाना? एक ही बात बार बार पूछना? यह सिर्फ बुढ़ापा नहीं, अल्ज़ाइमर का संकेत हो सकता है. आज जानिए अल्ज़ाइमर की जांच कैसे होती है. आखिर तक देखिए.",
 "अल्ज़ाइमर, डिमेंशिया का सबसे आम कारण है. इसमें दिमाग की कोशिकाएं धीरे धीरे खराब होती हैं. याददाश्त, सोचने की क्षमता, और रोज़ के काम प्रभावित होते हैं. याद रखिए, यह बुढ़ापे का सामान्य हिस्सा नहीं है.",
 "इन संकेतों पर ध्यान दें. हाल की बातें भूल जाना. एक ही सवाल बार बार पूछना. जानी पहचानी जगह पर रास्ता भटक जाना. पैसे या रोज़ के कामों में दिक्कत. और स्वभाव या मूड में बदलाव.",
 "भारत में साठ साल से ऊपर के लगभग सात दशमलव चार प्रतिशत लोगों को डिमेंशिया है. यानी लगभग अठासी लाख लोग. यह महिलाओं में, और गांवों में, ज़्यादा पाया गया है.",
 "क्या अल्ज़ाइमर का कोई एक टेस्ट है? नहीं. डॉक्टर तीन तरह से जांच करते हैं. पहला, याददाश्त के टेस्ट, जैसे एम एम एस ई. दूसरा, खून की जांच. तीसरा, दिमाग का स्कैन.",
 "खून की जांच क्यों? क्योंकि याददाश्त की कुछ समस्याएं ठीक हो सकने वाली वजहों से होती हैं. विटामिन बी ट्वेल्व की कमी, थायरॉइड, शुगर, खून की कमी, और किडनी या लिवर की गड़बड़ी. इनका इलाज होने पर याददाश्त सुधर सकती है.",
 "दिमाग का एम आर आई, या सी टी स्कैन, स्ट्रोक, ट्यूमर, या पानी भरने जैसी दूसरी वजहों को देखने में मदद करता है. कुछ मामलों में पेट स्कैन, या रीढ़ के पानी की जांच भी होती है.",
 "और अब एक नया ब्लड टेस्ट भी उपलब्ध है. पी टाऊ दो सौ सत्रह और बीटा एमिलॉयड रेशियो. बस खून का सैंपल, और रिपोर्ट लगभग अड़तालीस घंटे में. यह पचास साल से ऊपर के उन लोगों के लिए है, जिनमें याददाश्त कमज़ोर होने के लक्षण हों. रिपोर्ट तीन तरह की आती है. पॉज़िटिव, यानी अल्ज़ाइमर से जुड़े बदलाव की ज़्यादा संभावना. ग्रे ज़ोन, यानी आगे और जांच की ज़रूरत हो सकती है. और नेगेटिव, यानी संभावना बहुत कम. याद रखें, यह स्क्रीनिंग टेस्ट नहीं है, और अकेले इससे निदान नहीं होता. डॉक्टर इसे बाकी जांच के साथ ही समझते हैं.",
 "अच्छी खबर. लैंसेट की एक बड़ी रिपोर्ट के अनुसार, डिमेंशिया के लगभग पैंतालीस प्रतिशत मामले रोके या टाले जा सकते हैं. बी पी, शुगर, और कोलेस्ट्रॉल कंट्रोल रखें. कम सुनाई या कम दिखाई दे, तो इलाज कराएं. रोज़ चलें, धूम्रपान न करें, और लोगों से मिलते जुलते रहें.",
 "याद रखें, कोई भी दवा सिर्फ डॉक्टर की सलाह से ही लें. क्या आपके घर में किसी बुज़ुर्ग की याददाश्त कमज़ोर हो रही है? कमेंट में बताइए, और शेयर करें. और ज़्यादा जानकारी के लिए, हमारा फेसबुक पेज और यूट्यूब चैनल फॉलो करें. हेल्थ टेस्ट सिम्प्लिफाइड. ध्यान दें, यह वीडियो केवल बीमारियों और टेस्ट के बारे में सामान्य जानकारी के लिए है. जानकारी समय के साथ बदल सकती है. अपनी स्थिति को इस वीडियो से न जोड़ें. हमेशा अपने डॉक्टर से ही सलाह लें, और उन्हीं की सलाह मानें.",
]
import os
d = os.environ.get("HTS_MODEL", "/tmp/hi/hi/")
s = Synthesizer(tts_checkpoint=d + "fastpitch/best_model.pth", tts_config_path=d + "fastpitch/config.json",
                vocoder_checkpoint=d + "hifigan/best_model.pth", vocoder_config=d + "hifigan/config.json", use_cuda=False)
durs = []
for i, l in enumerate(lines):
    f = f"/tmp/alz2r_{i}.wav"; s.save_wav(s.tts(l, speaker_name="female"), f)
    subprocess.run(["ffmpeg","-nostdin","-y","-loglevel","error","-i",f,"-af","rubberband=pitch=0.96:formant=preserved,equalizer=f=250:t=q:w=1:g=2,treble=g=-1.5:f=6000",f"/tmp/alz2_{i}.wav"],check=True); f=f"/tmp/alz2_{i}.wav"
    durs.append(float(subprocess.check_output(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", f]).decode()))
json.dump(durs, open("/tmp/alz2_durs.json", "w")); print([round(x, 1) for x in durs], round(sum(durs), 1))
